-- ----------------------------
-- Table structure for tickets
-- ----------------------------
DROP TABLE IF EXISTS `tickets`;
CREATE TABLE `tickets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `idUser` int NOT NULL,
  `sujet` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `description` text COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `telephone` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fichiers` text COLLATE utf8mb4_general_ci,
  `status` enum('OUVERT','EN_COURS','RESOLU','FERME') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OUVERT',
  `priority` enum('BASSE','NORMALE','HAUTE','URGENTE') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NORMALE',
  `assignedTo` int DEFAULT NULL,
  `reponse` text COLLATE utf8mb4_general_ci,
  `reponduPar` int DEFAULT NULL,
  `dateReponse` datetime DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `deletedAt` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_e522585e9439011828e606834e` (`uuid`),
  KEY `IDX_1cfb61a749963bfba02395e118` (`priority`),
  KEY `IDX_12b901b34113688b4786368510` (`status`),
  KEY `IDX_75204ca2334302e0fc9f46ec92` (`idUser`),
  KEY `FK_d1beac6cf7fa5a0742a693c9aa9` (`assignedTo`),
  KEY `FK_0028812e47be65d22f9d0959d56` (`reponduPar`),
  CONSTRAINT `FK_0028812e47be65d22f9d0959d56` FOREIGN KEY (`reponduPar`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_75204ca2334302e0fc9f46ec922` FOREIGN KEY (`idUser`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_d1beac6cf7fa5a0742a693c9aa9` FOREIGN KEY (`assignedTo`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

