-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `idRole` int NOT NULL,
  `idAgency` int NOT NULL,
  `idOffice` int unsigned DEFAULT NULL,
  `lastname` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `firstname` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `birthdate` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gender` varchar(1) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fonction` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `salt` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `avatar` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime(6) DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `deleted_at` datetime(6) DEFAULT NULL,
  `deletedBy` int DEFAULT NULL,
  `suspension_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `deletion_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `version` int DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DESACTIVE',
  `dateSaisie` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `sms_token` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sms_token_expires` datetime DEFAULT NULL,
  `is_verified` tinyint NOT NULL DEFAULT '0',
  `two_factor_enabled` tinyint NOT NULL DEFAULT '0',
  `two_factor_secret` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `last_login` datetime DEFAULT NULL,
  `login_attempts` int NOT NULL DEFAULT '0',
  `locked_until` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_951b8f1dfc94ac1d0301a14b7e` (`uuid`),
  UNIQUE KEY `IDX_97672ac88f789774dd47f7c8be` (`email`),
  UNIQUE KEY `IDX_a000cca60bcf04454e72769949` (`phone`),
  KEY `FK_8adb072236d4ef4db52d8632c1a` (`idRole`),
  KEY `FK_90da3425dfd8d57dafe7130cead` (`idAgency`),
  KEY `FK_013e4bd8608dcb216adbdb059b4` (`idOffice`),
  CONSTRAINT `FK_013e4bd8608dcb216adbdb059b4` FOREIGN KEY (`idOffice`) REFERENCES `office` (`id`),
  CONSTRAINT `FK_8adb072236d4ef4db52d8632c1a` FOREIGN KEY (`idRole`) REFERENCES `roles` (`id`),
  CONSTRAINT `FK_90da3425dfd8d57dafe7130cead` FOREIGN KEY (`idAgency`) REFERENCES `agency` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

